package com.learnagent.skill;
import com.learnagent.agent.AgentExecutionTracker;import com.learnagent.memory.*;import java.util.*;import org.springframework.ai.tool.annotation.*;import org.springframework.stereotype.Component;
@Component public class MemorySkill{private final FlashcardService cards;private final MemoryReviewService reviews;private final KnowledgeGraphService graph;private final AgentExecutionTracker tracker;public MemorySkill(FlashcardService cards,MemoryReviewService reviews,KnowledgeGraphService graph,AgentExecutionTracker tracker){this.cards=cards;this.reviews=reviews;this.graph=graph;this.tracker=tracker;}@Tool(description="Generate traceable candidate flashcards from the selected course material. Candidates require user approval before review.")public List<MemoryDtos.CardView>generateFlashcardCandidates(@ToolParam(description="Course ID")UUID courseId,@ToolParam(description="Optional document ID",required=false)UUID documentId,@ToolParam(description="Number of candidates from 1 to 10",required=false)Integer limit){return tracker.execute("Memory Skill","generateFlashcardCandidates",()->cards.generate(new MemoryDtos.GenerateRequest(courseId,documentId,limit)),values->"Generated "+values.size()+" candidate flashcards");}@Tool(description="Query up to twenty flashcards currently due for spaced repetition.")public List<MemoryDtos.CardView>queryDueReviews(@ToolParam(description="Optional course ID",required=false)UUID courseId){return tracker.execute("Memory Skill","queryDueReviews",()->reviews.due(courseId),values->"Found "+values.size()+" due flashcards");}@Tool(description="Start today's local FSRS review session. No model call is required for scheduling.")public MemoryDtos.ReviewSessionView startMemoryReview(@ToolParam(description="Optional course ID",required=false)UUID courseId){return tracker.execute("Memory Skill","startMemoryReview",()->reviews.start(new MemoryDtos.StartReviewRequest(courseId)),value->"Started memory review with "+value.plannedCount()+" cards");}@Tool(description="Read one flashcard explanation and traceable sources when the user asks for help.")public MemoryDtos.CardView explainFlashcard(@ToolParam(description="Flashcard ID")UUID cardId){return tracker.execute("Memory Skill","explainFlashcard",()->cards.get(cardId),value->"Loaded flashcard explanation");}@Tool(description="Read the course knowledge map with mastery and forgetting risk.")public MemoryDtos.GraphView queryKnowledgeMap(@ToolParam(description="Course ID")UUID courseId){return tracker.execute("Memory Skill","queryKnowledgeMap",()->graph.graph(courseId),value->"Loaded "+value.nodes().size()+" knowledge nodes");}}
